import os

# Example of checking directory permissions (not part of the original solution)
def check_directory_permissions(directory):
    try:
        # Check if directory is world-writable
        if os.access(directory, os.W_OK) and os.stat(directory).st_mode & 0o002:
            print(f"Directory {directory} is world-writable - insecure.")
        else:
            print(f"Directory {directory} has secure permissions.")
    except Exception as e:
        print(f"Error checking directory permissions: {e}")
